"""Conservative one-time correction for auto-generated legacy entity IDs.

Only the default IDs from old builds are updated. User-renamed entities
are never renamed, and the stable integration unique_id is never changed.
"""

from __future__ import annotations

import logging

from homeassistant.helpers import entity_registry as er, label_registry as lr
from homeassistant.util import slugify

from .const import CONF_POLICIES, DOMAIN
from .manager import get_settings
from .settings import stable_id

_LOGGER = logging.getLogger(__name__)

POLICY_ENTITY_KEYS: dict[str, tuple[str, ...]] = {
    "sensor": (
        "matching_devices",
        "last_purge_run",
        "last_run",
        "next_purge_run",
    ),
    "number": ("retention_days",),
    "select": ("target_label",),
    "switch": ("simulation", "preserve_boundary"),
}


def is_legacy_generated_id(entity_id: str, domain: str, label_name: str) -> bool:
    """Recognize only the label-only IDs generated by the old integration."""
    prefix = f"{domain}."
    if not entity_id.startswith(prefix):
        return False
    object_id = entity_id[len(prefix) :]
    base = slugify(label_name)
    if object_id == base:
        return True
    suffix = object_id.removeprefix(base + "_")
    return object_id.startswith(base + "_") and suffix.isdecimal()


def async_migrate_legacy_entity_ids(hass, config_entry) -> int:
    """Rename only uncustomized label-only entity IDs, without losing unique IDs.

    A user's custom entity_id or display name is always preserved. Any
    collision is handled by Home Assistant's registry; no entity is removed.
    """
    registry = er.async_get(hass)
    known_labels = lr.async_get(hass).labels
    settings = get_settings(config_entry)
    migrated = 0

    for label_id in settings[CONF_POLICIES]:
        label = known_labels.get(label_id)
        display_name = label.name if label is not None else label_id
        identity = stable_id(settings, label_id)
        for domain, keys in POLICY_ENTITY_KEYS.items():
            for key in keys:
                unique_id = f"{config_entry.entry_id}_{identity}_{key}"
                current_id = registry.async_get_entity_id(domain, DOMAIN, unique_id)
                if current_id is None:
                    continue
                registration = registry.async_get(current_id)
                if registration is None or registration.name is not None:
                    continue
                if not is_legacy_generated_id(current_id, domain, display_name):
                    continue

                desired_object_id = f"less_records_{slugify(label_id)}_{slugify(key)}"
                new_id = registry.async_get_available_entity_id(
                    domain, desired_object_id, current_entity_id=current_id
                )
                if new_id == current_id:
                    continue
                try:
                    registry.async_update_entity(current_id, new_entity_id=new_id)
                except (ValueError, RuntimeError):
                    _LOGGER.exception(
                        "LessRecords could not safely rename %s; leaving existing ID",
                        current_id,
                    )
                    continue
                _LOGGER.info("LessRecords entity ID updated: %s -> %s", current_id, new_id)
                migrated += 1

    return migrated
